import Foundation
import Testing
@testable import OpenClaw

/// Round 6-8 differential tests for the exec allowlist glob matcher.
///
/// Vectors and the raw-unit Canonicalize table come from the synced core
/// fixture `apps/shared/contracts/fixtures/exec-allowlist-glob-parity.json`
/// (`npm run contracts:sync`; generated by core's
/// `scripts/generate-exec-glob-parity-fixture.ts` from seed 0xEDEC6). Every
/// fixture expectation is the TypeScript reference result from
/// src/infra/exec-allowlist-pattern.ts; never hand-edit the fixture. The
/// canonicalize table follows the generating host's Unicode version
/// (`unicodeVersion`), so the oracle compares it with this runtime's Unicode
/// version under Case Pair Stability rather than exactly.
struct ExecGlobParityTests {
    private struct GlobParityFixture: Decodable {
        struct Vector: Decodable {
            let pattern: String
            let target: String
            let matches: Bool
        }

        struct CanonicalEntry: Decodable {
            let unit: UInt16
            let canonical: UInt16
        }

        let version: Int
        let seed: String
        /// Unicode version of the ICU case data that generated `canonicalize`
        /// (core's `process.versions.unicode`). Fixtures synced before core
        /// recorded it omit the key.
        let unicodeVersion: String?
        let vectors: [Vector]
        let canonicalize: [CanonicalEntry]
    }

    /// Same fixture-path helper style as the other parity tests
    /// (ExecAllowlistTests): walk from this file to the repo root and into the
    /// synced contracts fixtures directory.
    private static func fixtureURL(filename: String) -> URL {
        var repoRoot = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 {
            repoRoot.deleteLastPathComponent()
        }
        return repoRoot
            .appendingPathComponent("apps")
            .appendingPathComponent("shared")
            .appendingPathComponent("contracts")
            .appendingPathComponent("fixtures")
            .appendingPathComponent(filename)
    }

    private static func loadFixture() throws -> GlobParityFixture {
        let data = try Data(contentsOf: self.fixtureURL(filename: "exec-allowlist-glob-parity.json"))
        return try JSONDecoder().decode(GlobParityFixture.self, from: data)
    }

    // MARK: - Canonicalize drift (Unicode Case Pair Stability)

    /// One side of the canonicalize comparison: units whose canonical unit differs
    /// from the unit itself (identity units omitted, as in the fixture), tagged with
    /// the Unicode version of the case data that produced them.
    private struct CanonicalTable {
        /// Names this side in drift reports ("fixture", "host", "synthetic").
        let source: String
        let unicodeVersion: String
        let mappings: [UInt16: UInt16]
    }

    /// Synced fixtures that predate core's `unicodeVersion` key carry the canonicalize
    /// table that core stamped "17.0", unchanged, when it added the key
    /// (ExpansionX/WednesdayAI-core@233f7066). Remove once the synced fixture records
    /// the key.
    private static let unrecordedFixtureUnicodeVersion = "17.0"

    /// Unicode version of this runtime's case data: the newest `age` of any assigned
    /// scalar. Every Unicode release assigns new scalars, and `uppercased()` (behind
    /// `jsCanonicalUnit`) reads the same stdlib Unicode data.
    private static func hostUnicodeVersion() -> String {
        var newest: Unicode.Version = (major: 0, minor: 0)
        for value: UInt32 in 0...0x10FFFF {
            guard let age = Unicode.Scalar(value)?.properties.age else { continue }
            if age.major > newest.major || (age.major == newest.major && age.minor > newest.minor) {
                newest = age
            }
        }
        return "\(newest.major).\(newest.minor)"
    }

    /// Dotted-decimal components, as strict as core's compareUnicodeVersions: every
    /// component is a non-negative integer without sign, padding or leading zeros.
    private static func unicodeVersionComponents(_ version: String) -> [Int]? {
        var components: [Int] = []
        for part in version.split(separator: ".", omittingEmptySubsequences: false) {
            guard let value = Int(part), value >= 0, String(value) == part else { return nil }
            components.append(value)
        }
        return components
    }

    /// Negative, zero or positive as `lhs` is older than, equal to or newer than `rhs`;
    /// a missing trailing component compares as zero.
    private static func compareUnicodeVersions(_ lhs: [Int], _ rhs: [Int]) -> Int {
        for index in 0..<max(lhs.count, rhs.count) {
            let left = index < lhs.count ? lhs[index] : 0
            let right = index < rhs.count ? rhs[index] : 0
            if left != right {
                return left < right ? -1 : 1
            }
        }
        return 0
    }

    /// Mirrors core's canonicalizeDrift (src/infra/exec-allowlist-glob-parity-fixture.test.ts).
    /// Equal Unicode versions: any unit missing or different on either side is drift.
    /// Different versions: Unicode Case Pair Stability never changes or drops an existing
    /// pair, so the older table must be an entry-for-entry subset of the newer one.
    private static func canonicalizeDrift(fixture: CanonicalTable, host: CanonicalTable) -> [String] {
        guard let fixtureVersion = Self.unicodeVersionComponents(fixture.unicodeVersion) else {
            return ["\(fixture.source): invalid Unicode version \"\(fixture.unicodeVersion)\""]
        }
        guard let hostVersion = Self.unicodeVersionComponents(host.unicodeVersion) else {
            return ["\(host.source): invalid Unicode version \"\(host.unicodeVersion)\""]
        }
        let order = Self.compareUnicodeVersions(fixtureVersion, hostVersion)
        let older = order <= 0 ? fixture : host
        let newer = order <= 0 ? host : fixture
        var units = Set(older.mappings.keys)
        if order == 0 {
            units.formUnion(newer.mappings.keys)
        }
        return units.sorted().compactMap { unit -> String? in
            let olderCanonical = older.mappings[unit]
            let newerCanonical = newer.mappings[unit]
            guard olderCanonical != newerCanonical else { return nil }
            let olderText = olderCanonical.map(Self.unitLabel) ?? "itself"
            let newerText = newerCanonical.map(Self.unitLabel) ?? "itself"
            return "\(Self.unitLabel(unit)): \(older.source) Unicode \(older.unicodeVersion) maps to \(olderText), "
                + "\(newer.source) Unicode \(newer.unicodeVersion) maps to \(newerText)"
        }
    }

    private static func unitLabel(_ unit: UInt16) -> String {
        let hex = String(unit, radix: 16, uppercase: true)
        return "U+" + String(repeating: "0", count: 4 - hex.count) + hex
    }

    private static func syntheticTable(_ unicodeVersion: String, _ mappings: [UInt16: UInt16]) -> CanonicalTable {
        CanonicalTable(source: "synthetic", unicodeVersion: unicodeVersion, mappings: mappings)
    }

    // MARK: - V1: non-ASCII units never canonicalize down to ASCII

    @Test func `dotless i literal does not match an ascii i allowlist entry`() {
        let dir = NSTemporaryDirectory() + "oc-glob-parity-\(UUID().uuidString)"
        defer { try? FileManager.default.removeItem(atPath: dir) }
        // The allowlisted entry is the ASCII literal; the argv uses U+0131.
        // TS keeps U+0131 out of the ASCII case fold, so the segment misses
        // and an on-miss ask is required.
        let analysis = ExecCommandResolution.analyze(
            command: ["/tmp/ma\u{0131}l"],
            rawCommand: nil,
            cwd: nil,
            env: nil,
            processCwd: dir)
        #expect(analysis.ok)
        let outcome = ExecApprovalEvaluator.evaluatePolicy(
            security: .allowlist,
            shellCommand: nil,
            analysis: analysis,
            allowlist: [ExecAllowlistEntry(pattern: "/tmp/mail")],
            autoAllowSkills: false,
            skillTrust: [],
            cwd: nil)
        #expect(!outcome.allowlistSatisfied)
        #expect(!outcome.skillAllow)
        #expect(ExecApprovalHelpers.requiresAsk(
            ask: .onMiss,
            security: .allowlist,
            allowlistMatch: outcome.allowlistMatches.first,
            skillAllow: outcome.skillAllow))

        // ASCII I/i positive control: the same entry matches ASCII inputs
        // case-insensitively.
        let ascii = ExecCommandResolution.analyze(
            command: ["/tmp/mail"],
            rawCommand: nil,
            cwd: nil,
            env: nil,
            processCwd: dir)
        let asciiOutcome = ExecApprovalEvaluator.evaluatePolicy(
            security: .allowlist,
            shellCommand: nil,
            analysis: ascii,
            allowlist: [ExecAllowlistEntry(pattern: "/tmp/Mail")],
            autoAllowSkills: false,
            skillTrust: [],
            cwd: nil)
        #expect(asciiOutcome.allowlistSatisfied)

        // Other non-ASCII units that uppercase INTO ASCII stay unmatched too
        // (U+017F long s; TS-verified false both directions).
        #expect(!ExecAllowlistMatcher.matches(pattern: "/tmp/ſ", target: "/tmp/s"))
        #expect(!ExecAllowlistMatcher.matches(pattern: "/tmp/s", target: "/tmp/ſ"))
        // U+212A KELVIN SIGN lowercases to ASCII k during normalization on
        // both sides, so those DO match (TS-verified true).
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/k", target: "/tmp/K"))
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/K", target: "/tmp/k"))
        // U+0130 canonicalizes to itself (single-unit uppercase, non-ASCII).
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/\u{0130}x", target: "/tmp/\u{0130}x"))
    }

    // MARK: - V2: dot-derived tokens never consume JS line terminators

    @Test func `dot derived tokens never consume js line terminators`() {
        // `?` (dot) and `**` (dot-star) must reject exactly LF, CR, LS, PS.
        for terminator in ["\n", "\r", "\u{2028}", "\u{2029}"] {
            #expect(!ExecAllowlistMatcher.matches(pattern: "/tmp/?a", target: "/tmp/\(terminator)a"))
            #expect(!ExecAllowlistMatcher.matches(pattern: "/tmp/**/run", target: "/tmp/a\(terminator)b/run"))
        }
        // U+000B, U+000C and U+0085 are NOT JS line terminators: dot matches.
        for matchable in ["\u{000B}", "\u{000C}", "\u{0085}"] {
            #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/?a", target: "/tmp/\(matchable)a"))
        }
        // Single star compiles to [^/]* — a negated class that intentionally
        // consumes line terminators — and literals match them verbatim.
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/*", target: "/tmp/a\nb"))
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/a\n*b", target: "/tmp/a\nxb"))
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/a\nb", target: "/tmp/a\nb"))
    }

    // MARK: - V3: long patterns match iteratively (no native stack growth)

    @Test func `long separated wildcard patterns return without stack growth`() {
        let repetitions = 100_000
        let pattern = "/tmp/" + String(repeating: "*/", count: repetitions) + "*"
        let positive = "/tmp/" + String(repeating: "a/", count: repetitions) + "x"
        #expect(ExecAllowlistMatcher.matches(pattern: pattern, target: positive))

        // Negative: the trailing literal mismatch forces every star to
        // backtrack; still returns a plain false.
        let negative = "/tmp/" + String(repeating: "a/", count: repetitions) + "y/"
        #expect(!ExecAllowlistMatcher.matches(pattern: pattern, target: negative))

        // Wide single-star backtracking (heap frames, bounded work).
        let wideTarget = "/tmp/" + String(repeating: "a", count: 4_000)
        #expect(ExecAllowlistMatcher.matches(pattern: "/tmp/a*a", target: wideTarget))
        #expect(!ExecAllowlistMatcher.matches(pattern: "/tmp/*a*b", target: wideTarget))
    }

    @Test func `ambiguous many star late failure stays polynomial`() {
        // Reviewer W1 vector (46 units): without the failed-state set this
        // visits C(40, 20) suffix explorations before returning false.
        //
        // Deterministic complexity bound instead of wall clock (wall clock is
        // load-dependent and was flaky on CI): every failed walk memoizes its
        // (tokenIndex, unitIndex) state, so the matcher can never walk more
        // states than the state space holds — exploredStates <=
        // (pattern units + 1) * (target units + 1), i.e. c = 1. Compiled
        // tokens are 1-2 units each, so pattern units bound the token count.
        // The uncached pre-W1 search re-walked states under different prefix
        // histories and exceeded this bound.
        func stateBound(pattern: String, target: String) -> Int {
            (pattern.utf16.count + 1) * (target.utf16.count + 1)
        }

        let latePattern = "/tmp/" + String(repeating: "*a", count: 20) + "b"
        let lateMissTarget = "/tmp/" + String(repeating: "a", count: 40) + "c"
        let lateMiss = ExecAllowlistMatcher.matchCountingStates(pattern: latePattern, target: lateMissTarget)
        #expect(!lateMiss.matched)
        #expect(lateMiss.exploredStates <= stateBound(pattern: latePattern, target: lateMissTarget))

        // Positive control: the reachable final literal still matches.
        let lateHitTarget = "/tmp/" + String(repeating: "a", count: 40) + "b"
        let lateHit = ExecAllowlistMatcher.matchCountingStates(pattern: latePattern, target: lateHitTarget)
        #expect(lateHit.matched)
        #expect(lateHit.exploredStates <= stateBound(pattern: latePattern, target: lateHitTarget))

        // Scaled well past 200 units, miss and hit, under the same bound.
        let scaledPattern = "/tmp/" + String(repeating: "*a", count: 120) + "b"
        let scaledMissTarget = "/tmp/" + String(repeating: "a", count: 240) + "c"
        let scaledMiss = ExecAllowlistMatcher.matchCountingStates(pattern: scaledPattern, target: scaledMissTarget)
        #expect(!scaledMiss.matched)
        #expect(scaledMiss.exploredStates <= stateBound(pattern: scaledPattern, target: scaledMissTarget))

        let scaledHitTarget = "/tmp/" + String(repeating: "a", count: 240) + "b"
        let scaledHit = ExecAllowlistMatcher.matchCountingStates(pattern: scaledPattern, target: scaledHitTarget)
        #expect(scaledHit.matched)
        #expect(scaledHit.exploredStates <= stateBound(pattern: scaledPattern, target: scaledHitTarget))
    }

    // MARK: - Synced differential vectors (TypeScript ground truth)

    @Test func `synced glob vectors agree with the typescript reference`() throws {
        let fixture = try Self.loadFixture()
        // The synced fixture carries the full round-6..7 vector corpus
        // (targeted classes plus seeded random fuzz, seed 0xEDEC6).
        #expect(fixture.version == 1)
        #expect(fixture.seed == "0xEDEC6")
        #expect(fixture.vectors.count >= 500)
        var failures: [String] = []
        for vector in fixture.vectors {
            let actual = ExecAllowlistMatcher.matches(pattern: vector.pattern, target: vector.target)
            if actual != vector.matches {
                failures.append("\(vector.pattern) vs \(vector.target): expected \(vector.matches), got \(actual)")
            }
        }
        #expect(failures.isEmpty, "vector mismatches: \(failures.prefix(5))")
    }

    @Test func `canonicalize agrees with the javascript reference over every unit`() throws {
        let fixture = try Self.loadFixture()
        var hostMappings: [UInt16: UInt16] = [:]
        for value: UInt32 in 0...0xFFFF {
            let unit = UInt16(value)
            let canonical = ExecAllowlistMatcher.jsCanonicalUnit(unit)
            if canonical != unit {
                hostMappings[unit] = canonical
            }
        }
        let fixtureTable = CanonicalTable(
            source: "fixture",
            unicodeVersion: fixture.unicodeVersion ?? Self.unrecordedFixtureUnicodeVersion,
            mappings: Dictionary(
                fixture.canonicalize.map { ($0.unit, $0.canonical) },
                uniquingKeysWith: { _, last in last }))
        let hostTable = CanonicalTable(
            source: "host",
            unicodeVersion: Self.hostUnicodeVersion(),
            mappings: hostMappings)
        let drift = Self.canonicalizeDrift(fixture: fixtureTable, host: hostTable)
        #expect(drift.isEmpty, "canonicalize drift: \(drift.prefix(5))")
    }

    @Test func `canonicalize drift accepts mappings that only a newer unicode version adds`() {
        let unicode17 = Self.syntheticTable("17.0", [0x61: 0x41])
        let unicode18 = Self.syntheticTable("18.0", [0x61: 0x41, 0x0277: 0xA7DD, 0x027C: 0xA7E2])
        #expect(Self.canonicalizeDrift(fixture: unicode17, host: unicode18).isEmpty)
        #expect(Self.canonicalizeDrift(fixture: unicode18, host: unicode17).isEmpty)
        // Versions compare numerically, not as strings: 9.0 is older than 10.0.
        let unicode9 = Self.syntheticTable("9.0", [0x61: 0x41])
        let unicode10 = Self.syntheticTable("10.0", [0x61: 0x41, 0x0277: 0xA7DD])
        #expect(Self.canonicalizeDrift(fixture: unicode9, host: unicode10).isEmpty)
    }

    @Test func `canonicalize drift names a dropped or changed mapping`() {
        let older = Self.syntheticTable("17.0", [0x61: 0x41, 0x00B5: 0x039C])
        let newerDropped = Self.syntheticTable("18.0", [0x61: 0x41])
        let newerChanged = Self.syntheticTable("18.0", [0x61: 0x41, 0x00B5: 0x039D])
        let pairs = [(older, newerDropped), (newerDropped, older), (older, newerChanged), (newerChanged, older)]
        for (fixture, host) in pairs {
            let drift = Self.canonicalizeDrift(fixture: fixture, host: host)
            #expect(drift.count == 1)
            #expect(drift.first?.hasPrefix("U+00B5:") == true, "\(drift)")
        }
    }

    @Test func `canonicalize drift is exact at equal unicode versions`() {
        let base = Self.syntheticTable("17.0", [0x61: 0x41])
        let extra = Self.syntheticTable("17.0", [0x61: 0x41, 0x0277: 0xA7DD])
        // A missing trailing component compares as zero: 17 equals 17.0.
        let extraShort = Self.syntheticTable("17", [0x61: 0x41, 0x0277: 0xA7DD])
        for (fixture, host) in [(base, extra), (extra, base), (base, extraShort)] {
            let drift = Self.canonicalizeDrift(fixture: fixture, host: host)
            #expect(drift.count == 1)
            #expect(drift.first?.hasPrefix("U+0277:") == true, "\(drift)")
        }
        // An unparseable version is a failure, never a silent pass.
        let invalid = Self.syntheticTable("17.x", [0x61: 0x41])
        #expect(Self.canonicalizeDrift(fixture: invalid, host: base) == ["synthetic: invalid Unicode version \"17.x\""])
    }
}
